export function parseVote(text){const match=/^!reward\s+(pickup|delivery|movement)\s+([0-8])\s*$/i.exec(text.trim());if(!match)return null;const rule=match[1].toLowerCase(),value=Number(match[2]);if(rule==='movement'&&value>3)return null;return {rule,value};}
export function tallyVotes(votes,current){const result={...current};for(const rule of ['pickup','delivery','movement']){const counts=new Map();for(const vote of votes.values())if(vote.rule===rule)counts.set(vote.value,(counts.get(vote.value)||0)+1);if(counts.size){const sorted=[...counts].sort((a,b)=>b[1]-a[1]||a[0]-b[0]);result[rule]=sorted[0][0];}}return result;}
